<?php
/** Veyra Pro scheduled monitoring, incidents, alerts and auto-healing. */
function veyra_pro_monitoring_settings(): array {
    $d=['service_sync_enabled'=>1,'provider_health_enabled'=>1,'expire_suspend_enabled'=>1,'telegram_alerts_enabled'=>1,'usage_thresholds'=>'80,90,100','expiry_days'=>'3,1,0','provider_degraded_latency_ms'=>2000,'service_batch_size'=>100];
    if(!table_exists('monitoring_settings')) return $d;
    try{$r=db()->query('SELECT * FROM monitoring_settings WHERE id=1')->fetch();return $r?array_merge($d,$r):$d;}catch(Throwable $e){return $d;}
}
function veyra_pro_save_monitoring_settings(array $in): array {
    if(!table_exists('monitoring_settings')) throw new RuntimeException('MONITORING_SCHEMA_MISSING');
    $thresholds=array_values(array_unique(array_filter(array_map('intval',preg_split('/[^0-9]+/',(string)($in['usage_thresholds']??'80,90,100'))),fn($v)=>$v>=1&&$v<=100)));sort($thresholds);if(!$thresholds)$thresholds=[80,90,100];
    $days=array_values(array_unique(array_filter(array_map('intval',preg_split('/[^0-9]+/',(string)($in['expiry_days']??'3,1,0'))),fn($v)=>$v>=0&&$v<=365)));rsort($days);if(!$days)$days=[3,1,0];
    $q=db()->prepare('INSERT INTO monitoring_settings (id,service_sync_enabled,provider_health_enabled,expire_suspend_enabled,telegram_alerts_enabled,usage_thresholds,expiry_days,provider_degraded_latency_ms,service_batch_size) VALUES (1,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE service_sync_enabled=VALUES(service_sync_enabled),provider_health_enabled=VALUES(provider_health_enabled),expire_suspend_enabled=VALUES(expire_suspend_enabled),telegram_alerts_enabled=VALUES(telegram_alerts_enabled),usage_thresholds=VALUES(usage_thresholds),expiry_days=VALUES(expiry_days),provider_degraded_latency_ms=VALUES(provider_degraded_latency_ms),service_batch_size=VALUES(service_batch_size)');
    $q->execute([!empty($in['service_sync_enabled'])?1:0,!empty($in['provider_health_enabled'])?1:0,!empty($in['expire_suspend_enabled'])?1:0,!empty($in['telegram_alerts_enabled'])?1:0,implode(',',$thresholds),implode(',',$days),max(250,min(30000,(int)($in['provider_degraded_latency_ms']??2000))),max(10,min(1000,(int)($in['service_batch_size']??100)))]);return veyra_pro_monitoring_settings();
}
function veyra_pro_monitor_begin(string $type): int { if(!table_exists('monitoring_runs'))return 0;$q=db()->prepare('INSERT INTO monitoring_runs (run_type,status) VALUES (? ,"running")');$q->execute([$type]);return(int)db()->lastInsertId(); }
function veyra_pro_monitor_finish(int $id,array $s,array $details=[]): void { if($id<=0||!table_exists('monitoring_runs'))return;db()->prepare('UPDATE monitoring_runs SET status=?,scanned_count=?,success_count=?,warning_count=?,error_count=?,details_json=?,completed_at=NOW() WHERE id=?')->execute([($s['errors']??0)>0?'completed_with_errors':'completed',(int)($s['scanned']??0),(int)($s['success']??0),(int)($s['warnings']??0),(int)($s['errors']??0),json_encode($details,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$id]); }
function veyra_pro_monitor_notify_user(int $userId,string $title,string $body,int $serviceId,string $key): void {
    notify_user_event($userId,'service',$title,$body,null,'service',(string)$serviceId);
    $cfg=veyra_pro_monitoring_settings();if(empty($cfg['telegram_alerts_enabled']))return;
    try{$u=get_user_by_id($userId);if($u&&!empty($u['telegram_id']))send_msg((int)$u['telegram_id'],"🔔 <b>".h($title)."</b>\n\n".h($body));}catch(Throwable $e){error_log('[Veyra monitor notify] '.$e->getMessage());}
}
function veyra_pro_alert_once(int $serviceId,string $key,string $cycle,string $value,array $meta,callable $send): bool {
    if(!table_exists('service_alert_states')){$send();return true;}$q=db()->prepare('SELECT * FROM service_alert_states WHERE user_service_id=? AND alert_key=? LIMIT 1');$q->execute([$serviceId,$key]);$old=$q->fetch();if($old&&hash_equals((string)$old['cycle_key'],$cycle)&&empty($old['resolved_at']))return false;$send();
    db()->prepare('INSERT INTO service_alert_states (user_service_id,alert_key,cycle_key,last_value,sent_at,resolved_at,metadata_json) VALUES (?,?,?,?,NOW(),NULL,?) ON DUPLICATE KEY UPDATE cycle_key=VALUES(cycle_key),last_value=VALUES(last_value),sent_at=NOW(),resolved_at=NULL,metadata_json=VALUES(metadata_json)')->execute([$serviceId,$key,$cycle,$value,json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);return true;
}
function veyra_pro_resolve_alert(int $serviceId,string $key): void {if(table_exists('service_alert_states'))db()->prepare('UPDATE service_alert_states SET resolved_at=NOW() WHERE user_service_id=? AND alert_key=? AND resolved_at IS NULL')->execute([$serviceId,$key]);}
function veyra_pro_monitor_service_alerts(array $svc): array {
    $out=['sent'=>0,'expired'=>false];$id=(int)$svc['id'];$uid=(int)$svc['user_id'];$name=trim((string)($svc['display_name']??''))?:('Service #'.$id);$limit=(int)($svc['traffic_limit_bytes']??0);$used=(int)($svc['traffic_used_bytes']??0);$cfg=veyra_pro_monitoring_settings();
    if($limit>0){$pct=min(100,(int)floor(($used/$limit)*100));$thresholds=array_values(array_unique(array_map('intval',explode(',',(string)$cfg['usage_thresholds']))));sort($thresholds);$hit=null;foreach($thresholds as $t){$k='usage_'.$t;if($pct<$t)veyra_pro_resolve_alert($id,$k);elseif($hit===null||$t>$hit)$hit=$t;}if($hit!==null){$k='usage_'.$hit;$cycle='limit:'.$limit;if(veyra_pro_alert_once($id,$k,$cycle,(string)$pct,['percent'=>$pct,'limit'=>$limit,'used'=>$used],function()use($uid,$name,$id,$hit,$pct){veyra_pro_monitor_notify_user($uid,'هشدار مصرف سرویس',"مصرف {$name} به {$pct}٪ رسیده است (آستانه {$hit}٪).",$id,'usage_'.$hit);}))$out['sent']++;}}
    $exp=$svc['expires_at']??null;if($exp){$seconds=strtotime((string)$exp)-time();$days=(int)ceil($seconds/86400);$cycle='exp:'.(string)$exp;if($seconds<=0){$out['expired']=true;$k='expired';if(veyra_pro_alert_once($id,$k,$cycle,'expired',['expires_at'=>$exp],function()use($uid,$name,$id){veyra_pro_monitor_notify_user($uid,'سرویس منقضی شد',"سرویس {$name} منقضی شده است.",$id,'expired');}))$out['sent']++;}else{$thresholds=array_values(array_unique(array_map('intval',explode(',',(string)$cfg['expiry_days']))));sort($thresholds);$hit=null;foreach($thresholds as $d){if($d>0&&$seconds<=($d*86400)){$hit=$d;break;}}if($hit!==null){$k='expiry_'.$hit;if(veyra_pro_alert_once($id,$k,$cycle,(string)$days,['expires_at'=>$exp,'days'=>$days],function()use($uid,$name,$id,$hit){veyra_pro_monitor_notify_user($uid,'یادآوری انقضای سرویس',"تا انقضای {$name} حدود {$hit} روز باقی مانده است.",$id,'expiry_'.$hit);}))$out['sent']++;}}
    }
    return $out;
}
function veyra_pro_suspend_expired_service(int $serviceId): array {
    $cfg=veyra_pro_monitoring_settings();if(empty($cfg['expire_suspend_enabled']))return ['suspended'=>0];$s=veyra_service_record($serviceId);if(!$s||empty($s['expires_at'])||strtotime((string)$s['expires_at'])>time())return ['suspended'=>0];
    $q=db()->prepare("SELECT * FROM service_instances WHERE user_service_id=? AND status NOT IN ('deleted','expired')");$q->execute([$serviceId]);$n=0;$errors=[];foreach($q->fetchAll()?:[] as $i){try{$external=(string)($i['external_username']?:$i['external_client_id']);if($external==='')continue;veyra_provider_driver((int)$i['provider_id'])->suspendService($external);db()->prepare('UPDATE service_instances SET status="expired" WHERE id=?')->execute([(int)$i['id']]);$n++;}catch(Throwable $e){$errors[]=['instance_id'=>(int)$i['id'],'error'=>$e->getMessage()];}}
    db()->prepare('UPDATE user_services SET status="expired" WHERE id=?')->execute([$serviceId]);if($n>0)db()->prepare('INSERT INTO service_events (user_service_id,event_type,title,details_json) VALUES (?,"expired_automated","Service expired automatically",?)')->execute([$serviceId,json_encode(['suspended_instances'=>$n,'errors'=>$errors],JSON_UNESCAPED_SLASHES)]);return ['suspended'=>$n,'errors'=>$errors];
}
function veyra_pro_run_service_monitor(int $limit=0): array {
    $cfg=veyra_pro_monitoring_settings();if(empty($cfg['service_sync_enabled']))return ['disabled'=>true,'scanned'=>0,'success'=>0,'warnings'=>0,'errors'=>0];$limit=$limit>0?$limit:(int)$cfg['service_batch_size'];$limit=max(1,min(1000,$limit));$rid=veyra_pro_monitor_begin('services');$s=['scanned'=>0,'success'=>0,'warnings'=>0,'errors'=>0,'alerts'=>0,'expired'=>0];$errs=[];
    $rows=db()->query("SELECT id FROM user_services WHERE status IN ('active','pending','degraded','suspended') ORDER BY COALESCE(last_sync_at,'2000-01-01') ASC,id ASC LIMIT ".$limit)->fetchAll(PDO::FETCH_COLUMN)?:[];
    foreach($rows as $sid){$s['scanned']++;try{$pub=veyra_sync_service((int)$sid,true);$rec=veyra_service_record((int)$sid);if(!$rec)throw new RuntimeException('SERVICE_NOT_FOUND_AFTER_SYNC');$a=veyra_pro_monitor_service_alerts($rec);$s['alerts']+=(int)$a['sent'];if(!empty($a['expired'])){$x=veyra_pro_suspend_expired_service((int)$sid);$s['expired']++;if(!empty($x['errors']))$s['warnings']++;}$s['success']++;}catch(Throwable $e){$s['errors']++;$errs[]=['service_id'=>(int)$sid,'error'=>$e->getMessage()];}}
    veyra_pro_monitor_finish($rid,$s,['alerts'=>$s['alerts'],'expired'=>$s['expired'],'errors'=>array_slice($errs,0,20)]);return $s+['run_id'=>$rid];
}
function veyra_pro_provider_health_sample_state(array $health,int $degradedMs): string {if(empty($health['ok']))return 'offline';return (int)($health['latency_ms']??0)>$degradedMs?'degraded':'online';}
function veyra_pro_provider_health_streak(int $providerId,int $degradedMs): array {
    $q=db()->prepare('SELECT health_status,latency_ms FROM provider_health_logs WHERE provider_id=? ORDER BY id DESC LIMIT 4');$q->execute([$providerId]);$rows=$q->fetchAll()?:[];$states=[];
    foreach($rows as $r){$raw=strtolower((string)($r['health_status']??''));$ok=in_array($raw,['online','healthy','ok'],true);$states[]=$ok?(((int)($r['latency_ms']??0)>$degradedMs)?'degraded':'online'):'offline';}
    $bad=0;$good=0;foreach($states as $st){if($st==='online'){if($bad===0)$good++;else break;}else{if($good===0)$bad++;else break;}}
    return ['states'=>$states,'bad_streak'=>$bad,'good_streak'=>$good];
}
function veyra_pro_provider_incident_update(array $provider,array $health,int $degradedMs): array {
    if(!table_exists('provider_incidents'))return ['changed'=>false];$pid=(int)$provider['id'];$lat=(int)($health['latency_ms']??0);$sample=veyra_pro_provider_health_sample_state($health,$degradedMs);$streak=veyra_pro_provider_health_streak($pid,$degradedMs);$prev=strtolower((string)($provider['last_health_status']??$provider['status']??'unknown'));
    $q=db()->prepare("SELECT * FROM provider_incidents WHERE provider_id=? AND status='open' ORDER BY id DESC LIMIT 1");$q->execute([$pid]);$open=$q->fetch();
    // Hysteresis: two consecutive bad checks before degraded/offline; two good checks before recovery.
    if($sample==='online'){$state=($streak['good_streak']>=2||!in_array($prev,['offline','degraded'],true))?'online':$prev;if($state==='online'&&$open&&$streak['good_streak']>=2){db()->prepare('UPDATE provider_incidents SET status="resolved",resolved_at=NOW(),last_seen_at=NOW() WHERE id=?')->execute([(int)$open['id']]);notify_admins("✅ <b>اتصال پنل پایدار شد</b>\n".h((string)$provider['name'])."\nLatency: <code>{$lat} ms</code>");db()->prepare('UPDATE service_providers SET last_health_status="online",status="online" WHERE id=?')->execute([$pid]);return ['changed'=>true,'state'=>'recovered','incident_id'=>(int)$open['id'],'streak'=>$streak];}db()->prepare('UPDATE service_providers SET last_health_status=?,status=? WHERE id=?')->execute([$state,$state,$pid]);return ['changed'=>false,'state'=>$state,'pending_recovery'=>$state!=='online','streak'=>$streak];}
    if($streak['bad_streak']<2){$state=in_array($prev,['online','healthy'],true)?'online':$prev;db()->prepare('UPDATE service_providers SET last_health_status=?,status=? WHERE id=?')->execute([$state,$state,$pid]);return ['changed'=>false,'state'=>$state,'pending_confirmation'=>true,'sample'=>$sample,'streak'=>$streak];}
    $state=$sample;$sev=$state==='offline'?'critical':'warning';$msg=mb_substr((string)($health['message']??$state),0,1000);db()->prepare('UPDATE service_providers SET last_health_status=?,status=? WHERE id=?')->execute([$state,$state,$pid]);
    if($open){db()->prepare('UPDATE provider_incidents SET severity=?,last_seen_at=NOW(),occurrence_count=occurrence_count+1,message=?,metadata_json=? WHERE id=?')->execute([$sev,$msg,json_encode(['health'=>$health,'streak'=>$streak],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),(int)$open['id']]);return ['changed'=>false,'state'=>$state,'incident_id'=>(int)$open['id'],'streak'=>$streak];}
    $q=db()->prepare('INSERT INTO provider_incidents (provider_id,severity,status,title,message,metadata_json) VALUES (?,?,"open",?,?,?)');$q->execute([$pid,$sev,'Provider '.$state,$msg,json_encode(['health'=>$health,'streak'=>$streak],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)]);$iid=(int)db()->lastInsertId();notify_admins(($state==='offline'?'🚨':'⚠️')." <b>وضعیت پنل {$state}</b>\n".h((string)$provider['name'])."\nدو بررسی متوالی مشکل را تایید کردند.".($lat?"\nLatency: <code>{$lat} ms</code>":''));return ['changed'=>true,'state'=>$state,'incident_id'=>$iid,'streak'=>$streak];
}
function veyra_pro_run_provider_monitor(): array {
    $cfg=veyra_pro_monitoring_settings();if(empty($cfg['provider_health_enabled']))return ['disabled'=>true,'scanned'=>0,'success'=>0,'warnings'=>0,'errors'=>0];$rid=veyra_pro_monitor_begin('providers');$s=['scanned'=>0,'success'=>0,'warnings'=>0,'errors'=>0,'incidents_changed'=>0];$details=[];
    foreach(veyra_providers(true) as $p){$driverMeta=VeyraProviderRegistry::supportedDrivers()[(string)$p['driver']]??[];if(empty($driverMeta['live']))continue;$s['scanned']++;try{$h=veyra_test_provider((int)$p['id']);if(empty($h['ok'])){usleep(250000);$h=veyra_test_provider((int)$p['id']);$h['retried']=true;}$i=veyra_pro_provider_incident_update($p,$h,(int)$cfg['provider_degraded_latency_ms']);if(!empty($i['changed']))$s['incidents_changed']++;if(!empty($h['ok'])&&(int)($h['latency_ms']??0)<=(int)$cfg['provider_degraded_latency_ms'])$s['success']++;else $s['warnings']++;$details[]=['provider_id'=>(int)$p['id'],'health'=>$h,'incident'=>$i];}catch(Throwable $e){$s['errors']++;$h=['ok'=>false,'status'=>'offline','message'=>$e->getMessage(),'latency_ms'=>null];$i=veyra_pro_provider_incident_update($p,$h,(int)$cfg['provider_degraded_latency_ms']);if(!empty($i['changed']))$s['incidents_changed']++;$details[]=['provider_id'=>(int)$p['id'],'error'=>$e->getMessage(),'incident'=>$i];}}
    veyra_pro_monitor_finish($rid,$s,['providers'=>$details]);return $s+['run_id'=>$rid];
}
function veyra_pro_run_monitoring(int $serviceLimit=0): array {return ['providers'=>veyra_pro_run_provider_monitor(),'services'=>veyra_pro_run_service_monitor($serviceLimit)];}
function veyra_pro_monitoring_dashboard(): array {
    $out=['settings'=>veyra_pro_monitoring_settings(),'open_incidents'=>[],'recent_runs'=>[],'recent_alerts'=>[],'stats'=>['open_incidents'=>0,'degraded_services'=>0,'expired_services'=>0]];
    if(table_exists('provider_incidents')){$out['open_incidents']=db()->query("SELECT i.*,p.name provider_name,p.driver FROM provider_incidents i JOIN service_providers p ON p.id=i.provider_id WHERE i.status='open' ORDER BY FIELD(i.severity,'critical','warning'),i.opened_at DESC LIMIT 50")->fetchAll()?:[];$out['stats']['open_incidents']=count($out['open_incidents']);}
    if(table_exists('monitoring_runs'))$out['recent_runs']=db()->query('SELECT * FROM monitoring_runs ORDER BY id DESC LIMIT 30')->fetchAll()?:[];
    if(table_exists('service_alert_states'))$out['recent_alerts']=db()->query('SELECT a.*,s.display_name,u.telegram_id FROM service_alert_states a JOIN user_services s ON s.id=a.user_service_id JOIN users u ON u.id=s.user_id ORDER BY a.sent_at DESC LIMIT 30')->fetchAll()?:[];
    if(table_exists('user_services')){$out['stats']['degraded_services']=(int)db()->query("SELECT COUNT(*) FROM user_services WHERE status='degraded'")->fetchColumn();$out['stats']['expired_services']=(int)db()->query("SELECT COUNT(*) FROM user_services WHERE status='expired'")->fetchColumn();}
    return $out;
}
